// <npm-compat-chart src="...">
//
// Renders the committed npm-package-compatibility summary
// (benchmarks/results/npm-compat.json, generated by
// scripts/generate-npm-compat-report.mjs): a dashboard-style metrics row plus
// one card per package — compile/validate status, test pass rate (the
// package's own real test suite where one exists, otherwise a labeled
// differential-ops count — never conflated), and a head-to-head perf
// comparison of the compiled Wasm export against the SAME pinned package
// running natively under Node.
//
// Same fetch-at-runtime convention as t262-charts.js / trend-chart.js /
// perf-benchmark-chart.js — no build-time templating. Styling matches
// website/dashboard/index.html (dense, sharp-cornered, minimal chrome).

class NpmCompatChart extends HTMLElement {
  static get observedAttributes() {
    return ["src"];
  }

  connectedCallback() {
    this.attachShadow({ mode: "open" });
    this._load();
  }

  attributeChangedCallback() {
    if (this.isConnected && this.shadowRoot) this._load();
  }

  async _load() {
    const src = this.getAttribute("src");
    if (!src) return;
    this._renderLoading();
    try {
      const res = await fetch(src);
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      this._render(await res.json());
    } catch (err) {
      this._renderError(err);
    }
  }

  _renderLoading() {
    this.shadowRoot.innerHTML = `${this._styles()}<div class="msg">Loading…</div>`;
  }

  _renderError(err) {
    const m = err && err.message ? err.message : String(err);
    this.shadowRoot.innerHTML = `${this._styles()}<div class="msg error">Failed to load: ${this._esc(m)}</div>`;
  }

  _esc(s) {
    const d = document.createElement("div");
    d.textContent = s;
    return d.innerHTML;
  }

  _fmtDate(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    if (Number.isNaN(d.valueOf())) return "";
    return d.toISOString().slice(0, 10);
  }

  _fmtMs(us) {
    if (us == null) return "—";
    const ms = us / 1000;
    if (ms >= 1000) return `${(ms / 1000).toFixed(2)}s`;
    if (ms >= 1) return `${ms.toFixed(1)}ms`;
    return `${us.toFixed(1)}µs`;
  }

  // ratio = nodeUs / wasmUs. >1 => wasm faster. <1 => node faster.
  _perfLabel(ratio) {
    if (ratio == null) return { text: "—", cls: "" };
    if (ratio >= 1) return { text: `${ratio.toFixed(2)}× faster`, cls: "good" };
    return { text: `${(1 / ratio).toFixed(0)}× slower`, cls: "bad" };
  }

  _row(label, valueHtml, cls) {
    return `<div class="row"><span class="k">${this._esc(label)}</span><span class="v ${cls || ""}">${valueHtml}</span></div>`;
  }

  _card(pkg) {
    const compiles = pkg.compile?.success;
    const validates = pkg.validation?.validates;

    const badge = (ok, label) =>
      `<span class="badge ${ok === true ? "ok" : ok === false ? "bad" : ""}">${this._esc(label)}</span>`;

    // Tests — the "own test suite" vs "differential ops" distinction is
    // load-bearing, so it is the row's own label, never blurred into one number.
    let tests;
    if (!pkg.tests) {
      tests = this._row("tests", `<span class="muted">n/a — compile blocked</span>`);
    } else {
      const { kind, passed, total, passRatePct } = pkg.tests;
      const pct = passRatePct != null ? passRatePct : total ? ((passed / total) * 100).toFixed(1) : null;
      const label = kind === "official-suite" ? "own test suite" : "differential ops";
      tests = this._row(
        "tests",
        `<span class="mono">${passed}/${total}</span>${pct != null ? ` <span class="muted">${pct}%</span>` : ""} <span class="tag">${this._esc(label)}</span>`,
      );
    }

    // Perf
    let perf;
    if (!pkg.perf) {
      perf = this._row("perf vs node", `<span class="muted">not measured</span>`);
    } else {
      const { sampleOp, wasmUs, nodeUs, ratio } = pkg.perf;
      const l = this._perfLabel(ratio);
      perf =
        this._row(
          "perf vs node",
          `<span class="${l.cls}">${l.text}</span> <span class="muted mono">${this._fmtMs(wasmUs)} vs ${this._fmtMs(nodeUs)}</span>`,
        ) + `<div class="row sub"><span class="k"></span><span class="v muted">${this._esc(sampleOp)}</span></div>`;
    }

    const bugs = (pkg.knownBugs ?? []).length
      ? this._row(
          "open issues",
          pkg.knownBugs
            .map(
              (b) =>
                `<a href="https://github.com/loopdive/js2/issues/${b.issue}" target="_blank" rel="noopener" title="${this._esc(b.summary)}">#${b.issue}</a>`,
            )
            .join(" "),
        )
      : "";

    return `
      <div class="card">
        <div class="card-top">
          <span class="name">${this._esc(pkg.name)}</span>
          <span class="ver mono">v${this._esc(pkg.version)}</span>
          <a class="issue" href="https://github.com/loopdive/js2/issues/${pkg.issue}" target="_blank" rel="noopener">#${pkg.issue}</a>
        </div>
        <div class="badges">${badge(compiles, "compiles")}${badge(validates, "validates")}</div>
        <div class="rows">${tests}${perf}${bugs}</div>
        <div class="entry mono">${this._esc(pkg.entryFile)}</div>
      </div>`;
  }

  _render(data) {
    const pkgs = data.packages ?? [];
    const compiling = pkgs.filter((p) => p.compile?.success).length;
    const validating = pkgs.filter((p) => p.validation?.validates).length;
    const metric = (v, l) => `<div class="metric"><span class="value">${v}</span><span class="label">${l}</span></div>`;

    this.shadowRoot.innerHTML = `
      ${this._styles()}
      <div class="metrics">
        ${metric(pkgs.length, "packages")}
        ${metric(`${compiling}/${pkgs.length}`, "compile")}
        ${metric(`${validating}/${pkgs.length}`, "validate")}
        ${metric(this._fmtDate(data.generatedAt) || "—", "measured")}
      </div>
      <div class="cards">${pkgs.map((p) => this._card(p)).join("")}</div>
      ${data.note ? `<p class="note">${this._esc(data.note)}</p>` : ""}
    `;
  }

  _styles() {
    return `
      <style>
        :host {
          display: block;
          font-family: var(--font, Inter, ui-sans-serif, system-ui, sans-serif);
          color: var(--text, #fff);
        }
        .mono { font-family: var(--mono, "JetBrains Mono", "SF Mono", monospace); }
        .muted { color: var(--text-muted, rgba(255,255,255,0.46)); }
        .good { color: var(--green, #4ade80); }
        .bad { color: var(--red, #f87171); }
        .msg { padding: 48px; text-align: center; color: var(--text-muted, rgba(255,255,255,0.46)); }
        .msg.error { color: var(--red, #f87171); }

        /* Dashboard-style metrics row: big number, tiny uppercase label, no box */
        .metrics {
          display: flex;
          justify-content: space-evenly;
          flex-wrap: wrap;
          gap: 16px;
          padding: 22px 0 26px;
        }
        .metric { display: flex; flex-direction: column; align-items: center; white-space: nowrap; }
        .metric .value {
          font-size: 28px;
          font-weight: 700;
          line-height: 1;
          letter-spacing: -0.05em;
          margin-bottom: 8px;
        }
        .metric .label {
          font-size: 10px;
          color: rgba(255, 255, 255, 0.35);
          text-transform: uppercase;
          letter-spacing: 0.08em;
        }

        .cards {
          display: grid;
          grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
          gap: 1px;
          background: var(--border, rgba(255,255,255,0.12));
          border: 1px solid var(--border, rgba(255,255,255,0.12));
        }
        .card { background: var(--bg, #060a14); padding: 14px 16px 12px; }
        .card-top { display: flex; align-items: baseline; gap: 8px; margin-bottom: 10px; }
        .card-top .name { font-size: 15px; font-weight: 600; }
        .card-top .ver { font-size: 11px; color: var(--text-muted, rgba(255,255,255,0.46)); }
        .card-top .issue {
          margin-left: auto;
          font-size: 11px;
          color: var(--text-muted, rgba(255,255,255,0.46));
          text-decoration: none;
        }
        .card-top .issue:hover { text-decoration: underline; }

        .badges { display: flex; gap: 6px; margin-bottom: 10px; }
        .badge {
          font-size: 10px;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          padding: 2px 6px;
          border: 1px solid currentColor;
          color: var(--text-muted, rgba(255,255,255,0.46));
        }
        .badge.ok { color: var(--green, #4ade80); }
        .badge.bad { color: var(--red, #f87171); }

        .rows { display: flex; flex-direction: column; }
        .row {
          display: flex;
          justify-content: space-between;
          align-items: baseline;
          gap: 10px;
          font-size: 12px;
          padding: 5px 0;
          border-bottom: 1px solid rgba(255, 255, 255, 0.06);
        }
        .row:last-child { border-bottom: none; }
        .row.sub { padding-top: 0; margin-top: -4px; border-bottom: none; font-size: 11px; }
        .row .k {
          color: rgba(255, 255, 255, 0.35);
          text-transform: uppercase;
          font-size: 10px;
          letter-spacing: 0.06em;
          white-space: nowrap;
        }
        .row .v { text-align: right; }
        .row .v a { color: var(--accent, #6c8aff); text-decoration: none; }
        .row .v a:hover { text-decoration: underline; }
        .tag {
          font-size: 9px;
          text-transform: uppercase;
          letter-spacing: 0.06em;
          color: rgba(255, 255, 255, 0.35);
          border: 1px solid rgba(255, 255, 255, 0.14);
          padding: 1px 4px;
          margin-left: 2px;
        }
        .entry {
          margin-top: 10px;
          font-size: 10px;
          color: rgba(255, 255, 255, 0.3);
        }
        .note {
          margin-top: 18px;
          font-size: 11px;
          color: var(--text-muted, rgba(255,255,255,0.46));
          max-width: 900px;
        }
      </style>
    `;
  }
}

customElements.define("npm-compat-chart", NpmCompatChart);
